.darma-loader-tw-wave-dots { display: inline-flex; align-items: center; justify-content: center; gap: calc(var(--loader-size, 90px) * .07); width: var(--loader-size, 90px); height: calc(var(--loader-size, 90px) * .45); }
.darma-loader-tw-wave-dots span { width: calc(var(--loader-size, 90px) * .11); height: calc(var(--loader-size, 90px) * .11); border-radius: 9999px; background: var(--loader-color, #0ea5e9); animation: darma-loader-tw-wave-dots-twWave calc(var(--loader-speed, 1s) * 1.4) ease-in-out infinite; }
.darma-loader-tw-wave-dots span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * .1); }
.darma-loader-tw-wave-dots span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * .2); }
.darma-loader-tw-wave-dots span:nth-child(4) { animation-delay: calc(var(--loader-speed, 1s) * .3); }
.darma-loader-tw-wave-dots span:nth-child(5) { animation-delay: calc(var(--loader-speed, 1s) * .4); }
@keyframes darma-loader-tw-wave-dots-twWave { 0%, 100% { transform: translateY(55%); opacity: .4; } 50% { transform: translateY(-55%); opacity: 1; } }

